import { useState, type FormEvent, type ReactNode } from "react";
import { createFileRoute, Link, useNavigate } from "@tanstack/react-router";
import { useQuery } from "@tanstack/react-query";
import { ArrowRight, BadgeCheck, Bell, Bookmark, Building2, CalendarDays, ChevronRight, CircleAlert, CircleCheck, CircleX, CloudUpload, Database, ExternalLink, FileQuestion, FileText, MapPin, Search, ShieldCheck } from "lucide-react";
import { apiFetch } from "@/lib/api";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { DashboardCard, CompactEmpty } from "@/components/dashboard/DashboardCard";
import { ErrorState, LoadingState } from "@/components/states/DataStates";
import { useProfile, useSession } from "@/hooks/useSession";
import { useLanguage } from "@/lib/language";
import { DASHBOARD_TRANSLATIONS } from "@/lib/dashboard-translations";
import heroDay from "@/assets/auth/government-day.jpg";
import heroNight from "@/assets/auth/government-night.jpg";
import { useTheme } from "@/lib/theme";
import { BID_STATUSES, fetchMyBids, fetchPublishedTenders, fmtDate, inr, type BidStatus } from "@/lib/procurement";

export const Route=createFileRoute("/_authenticated/vendor/dashboard")({head:()=>({meta:[{title:"Vendor Dashboard — GeMShield"},{name:"description",content:"Track tender opportunities, bid submissions and compliance status."},{property:"og:title",content:"Vendor Dashboard — GeMShield"},{property:"og:description",content:"Track tender opportunities, bid submissions and compliance status."},{property:"og:type",content:"website"},{name:"twitter:card",content:"summary"}]}),component:VendorDashboard});

function Field({label,icon:Icon,children}:{label:string;icon?:typeof Search;children:ReactNode}){return <label className="min-w-0"><span className="mb-1 block text-[10px] font-semibold text-foreground">{label}</span><span className="relative block">{Icon&&<Icon className="pointer-events-none absolute left-2.5 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-muted-foreground"/>}{children}</span></label>}
function VendorDashboard(){const {language}=useLanguage();const t=DASHBOARD_TRANSLATIONS[language];const v=t.vendor;const {theme}=useTheme();const {session}=useSession();const {data:profile}=useProfile();const navigate=useNavigate();const [q,setQ]=useState("");const userId=session?.user.id;
 const notifications=useQuery({queryKey:["vendor","notifications","recent",userId],enabled:Boolean(userId),queryFn:async()=>{const data=await apiFetch<any>("/api/notifications?limit=3");return data.notifications;}});
 const vendor=useQuery({queryKey:["vendor","record",userId],enabled:Boolean(userId),queryFn:async()=>{if(!userId)return null;try{const data=await apiFetch<any>("/api/vendors/me");return data;}catch{return null;}}});
  const tenders=useQuery({queryKey:["tenders","latest"],enabled:Boolean(userId),queryFn:()=>fetchPublishedTenders({},{},5)});
  const bids=useQuery({queryKey:["bids","mine",userId],enabled:Boolean(userId),queryFn:()=>fetchMyBids(userId!)});
  const [tab,setTab]=useState<BidStatus>("draft");const labels=[v.drafts,v.submitted,v.review,v.clarification,v.completed];const tabBids=(bids.data??[]).filter(b=>b.status===tab);
  const firstName=(profile?.profile?.full_name||"").split(" ").at(0)??""; const search=(e:FormEvent)=>{e.preventDefault();navigate({to:"/vendor/find-tenders",search:(q.trim()?{q:q.trim()}:{}) as never});};
 return <div className="mx-auto max-w-[1320px] space-y-2.5">
  <section className="relative min-h-40 overflow-hidden rounded-lg border border-border"><img src={theme==="dark"?heroNight:heroDay} alt="" aria-hidden className="absolute inset-0 h-full w-full object-cover"/><div className="absolute inset-0 bg-gradient-to-r from-card via-card/90 to-card/5"/><div className="relative z-10 max-w-xl px-7 py-5"><span className="tricolour-rule mb-2 w-10"/><p className="text-[10px] font-semibold uppercase tracking-[0.16em] text-muted-foreground">{v.eyebrow}</p><h1 className="mt-1 font-display text-3xl font-bold text-foreground">{firstName?`${v.welcomeNamed}, ${firstName}`:v.welcome}</h1><p className="mt-1 max-w-md text-sm leading-snug text-muted-foreground">{v.intro}</p></div><blockquote className="absolute right-7 top-8 hidden w-52 border-l border-border pl-4 font-display text-sm italic leading-snug text-foreground xl:block">“{v.quote}”</blockquote>
  </section>
  <DashboardCard icon={Search} title={v.find} subtitle={v.findSub} action={<div className="flex gap-2"><Button variant="ghost" size="sm" asChild><Link to="/vendor/find-tenders"><Bookmark className="mr-1.5 h-3.5 w-3.5"/>{v.saved}</Link></Button><Button size="sm" asChild><Link to="/vendor/find-tenders">{v.viewTenders}<ArrowRight className="ml-1.5 h-3.5 w-3.5"/></Link></Button></div>}>
   <form onSubmit={search} className="grid gap-2 border-t border-border px-4 py-3 sm:grid-cols-2 lg:grid-cols-[1.2fr_1fr_1.1fr_1fr_1.2fr_.8fr_auto]"><Field label={v.keyword} icon={Search}><Input value={q} onChange={e=>setQ(e.target.value)} placeholder={v.keywordHint} className="h-8 pl-8 text-[11px]"/></Field>{[{label:v.category,value:v.allCategories},{label:v.department,value:v.allDepartments},{label:v.location,value:v.allIndia},{label:v.closing,value:"—"},{label:v.eligibility,value:v.all}].map(({label,value})=><Field key={label} label={label}><select className="h-8 w-full rounded-md border border-input bg-background px-2 text-[11px] text-foreground"><option>{value}</option></select></Field>)}<Button type="submit" size="sm" className="mt-auto h-8"><Search className="mr-1.5 h-3.5 w-3.5"/>{v.search}</Button></form>
    {tenders.isPending?<div className="p-3"><LoadingState label={t.states.loading}/></div>:tenders.error?<div className="p-3"><ErrorState error={tenders.error} onRetry={()=>tenders.refetch()}/></div>:tenders.data?.length?<ul className="border-t border-border">{tenders.data.map(td=><li key={td.id}><Link to="/vendor/tenders/$tenderId" params={{tenderId:td.id}} className="flex items-center gap-3 border-b border-border px-4 py-2 text-[11px] last:border-0 hover:bg-accent/30"><span className="min-w-0 flex-1"><b className="block truncate">{td.title}</b><small className="text-muted-foreground">{td.reference_no} · {td.department??"—"}</small></span><span className="hidden text-muted-foreground sm:block"><CalendarDays className="mr-1 inline h-3 w-3"/>{fmtDate(td.closing_at)}</span><ChevronRight className="h-3.5 w-3.5 text-muted-foreground"/></Link></li>)}</ul>:<CompactEmpty icon={FileQuestion} title={v.opportunityEmpty} description={v.opportunityHelp}/>}
   </DashboardCard>
   <div className="grid gap-2.5 xl:grid-cols-2"><DashboardCard icon={FileText} tone="orange" title={v.bids} subtitle={v.bidsSub} action={<Button variant="outline" size="sm" asChild><Link to="/vendor/my-bids">{v.viewAll}<ArrowRight className="ml-1.5 h-3.5 w-3.5"/></Link></Button>}><div role="tablist" className="grid grid-cols-5 border-y border-border bg-muted/40 text-center text-[10px]">{BID_STATUSES.map((s,i)=><button type="button" role="tab" aria-selected={tab===s} key={s} onClick={()=>setTab(s)} className={tab===s?"border-b-2 border-primary px-1 py-2 font-semibold text-primary":"px-1 py-2 text-muted-foreground hover:text-foreground"}>{labels[i]} {bids.data?`(${bids.data.filter(b=>b.status===s).length})`:""}</button>)}</div>{bids.isPending?<div className="p-3"><LoadingState label={t.states.loading}/></div>:bids.error?<div className="p-3"><ErrorState error={bids.error} onRetry={()=>bids.refetch()}/></div>:tabBids.length?<ul>{tabBids.slice(0,5).map(b=><li key={b.id}><Link to="/vendor/my-bids/$bidId" params={{bidId:b.id}} className="flex items-center gap-3 border-b border-border px-4 py-2 text-[11px] last:border-0 hover:bg-accent/30"><span className="min-w-0 flex-1"><b className="block truncate">{b.tender?.title}</b><small className="text-muted-foreground">{b.tender?.reference_no} · {fmtDate(b.updated_at)}</small></span><span>{inr(b.quoted_amount)}</span><ChevronRight className="h-3.5 w-3.5 text-muted-foreground"/></Link></li>)}</ul>:<CompactEmpty icon={FileText} title={`${labels[BID_STATUSES.indexOf(tab)]}: 0`} description={v.noBidsHelp}/>}</DashboardCard>
   <DashboardCard icon={ShieldCheck} tone="green" title={v.compliance} subtitle={v.complianceSub} action={<Button variant="outline" size="sm" asChild><Link to="/vendor/compliance">{v.newVerification}<ArrowRight className="ml-1.5 h-3.5 w-3.5"/></Link></Button>}><div className="grid gap-2 border-t border-border p-3 md:grid-cols-[1.8fr_1fr]"><Link to="/vendor/compliance" className="flex min-h-36 flex-col items-center justify-center rounded-md border border-dashed border-border p-4 text-center hover:bg-accent/30"><CloudUpload className="h-8 w-8 text-muted-foreground"/><b className="mt-2 text-xs">{v.upload}</b><span className="text-[10px] text-muted-foreground">{v.uploadHelp}</span><span className="mt-3 rounded-md bg-primary px-8 py-2 text-[11px] font-semibold text-primary-foreground">{v.choose}</span><span className="mt-2 text-[10px] text-muted-foreground">{v.drag}</span></Link><div className="rounded-md border border-border p-2"><b className="text-xs">{v.verificationStatus}</b><p className="text-[10px] text-muted-foreground">{v.statusHelp}</p>{[{Icon:CircleCheck,title:v.compliant,sub:v.meets,color:"text-success"},{Icon:CircleAlert,title:v.needsReview,sub:v.attention,color:"text-warning"},{Icon:CircleX,title:v.nonCompliant,sub:v.critical,color:"text-destructive"}].map(({Icon,title,sub,color})=><div key={title} className="mt-1.5 flex items-center gap-2 rounded-md bg-muted/50 p-2"><Icon className={`h-5 w-5 ${color}`}/><span><b className={`block text-[10px] ${color}`}>{title}</b><small className="block text-[9px] text-muted-foreground">{sub}</small></span></div>)}</div></div></DashboardCard></div>
  <div className="grid gap-2.5 xl:grid-cols-3"><DashboardCard icon={BadgeCheck} tone="purple" title={v.passport} subtitle={v.passportSub} action={<Button variant="outline" size="sm" asChild><Link to="/vendor/bid-passport">{v.viewRecords}<ChevronRight className="ml-1 h-3.5 w-3.5"/></Link></Button>}><CompactEmpty icon={BadgeCheck} title={v.noPassport} description={v.noPassportHelp}/></DashboardCard>
   <DashboardCard icon={Bell} tone="orange" title={v.recent} action={<Button variant="outline" size="sm" asChild><Link to="/vendor/notifications">{v.viewAll}<ChevronRight className="ml-1 h-3.5 w-3.5"/></Link></Button>}>{notifications.isPending?<div className="p-3"><LoadingState label={t.states.loading}/></div>:notifications.error?<div className="p-3"><ErrorState error={notifications.error} onRetry={()=>notifications.refetch()}/></div>:notifications.data?.length?<ul className="border-t border-border p-2">{notifications.data.map(n=><li key={n.id} className="border-b border-border p-2 last:border-0"><b className="text-[11px]">{n.title}</b>{n.body&&<p className="text-[10px] text-muted-foreground">{n.body}</p>}</li>)}</ul>:<CompactEmpty icon={Bell} title={v.noNotifications} description={v.notificationHelp}/>}</DashboardCard>
   <DashboardCard icon={Database} title={v.openData} subtitle={v.openDataSub}><ul className="border-t border-border p-2">{[{Icon:Building2,title:v.company,sub:v.companyBy},{Icon:BadgeCheck,title:v.msme,sub:v.msmeBy},{Icon:MapPin,title:v.otherData,sub:v.otherBy}].map(({Icon,title,sub})=><li key={title}><a href="https://www.data.gov.in/" target="_blank" rel="noreferrer noopener" className="flex items-center gap-2 rounded-md border-b border-border p-2 last:border-0 hover:bg-accent/30"><Icon className="h-4 w-4 text-info"/><span className="min-w-0"><b className="block truncate text-[10px]">{title}</b><small className="block truncate text-[9px] text-muted-foreground">{sub}</small></span><ExternalLink className="ml-auto h-3 w-3 text-info"/></a></li>)}</ul><p className="border-t border-border px-3 py-2 text-[9px] text-muted-foreground">{v.sourceNote}</p></DashboardCard></div>
  {vendor.data&&vendor.data.onboarding_status!=="verified"&&<div className="flex items-center gap-3 rounded-lg border border-warning/40 bg-warning/10 p-3 text-xs"><CircleAlert className="h-4 w-4 text-warning"/><span>{v.onboarding}</span><Button variant="outline" size="sm" className="ml-auto" asChild><Link to="/vendor/profile">{v.completeProfile}</Link></Button></div>}
 </div>}
